    def write_debug_state(self, case, threads, data_brief, negotiation, payload):
        """Atomically keep the latest auditable turn at the workspace root."""
        turn = sum(message.get("from") == "buyer" for events in threads.values() for message in events) + 1
        state = {
            "timestamp_utc": datetime.now(timezone.utc).isoformat(),
            "case_id": case.get("case_id"),
            "turn": turn,
            "roles": {
                "analyst": {
                    "status": data_brief.get("status", "failed"),
                    "historical_rows": data_brief.get("historical_row_count", 0),
                    "index_deltas": data_brief.get("index_delta_count", 0),
                },
                "negotiator": {
                    "status": "failed" if negotiation.get("kind") == "error_fallback" else "complete",
                    **negotiation,
                },
                "validator": {
                    "status": "fallback" if negotiation.get("kind") == "validator_fallback" else "complete",
                    "final_payload": payload,
                },
            },
            "analysis": {
                "decision_summary": negotiation.get("decision_summary", ""),
                "data_rebuttal": negotiation.get("data_rebuttal", ""),
            },
            "data_brief": data_brief,
            "negotiation": negotiation,
            "final_payload": payload,
        }
        temp_path = None
        try:
            with DEBUG_STATE_LOCK:
                with tempfile.NamedTemporaryFile(
                    mode="w", encoding="utf-8", dir=DEBUG_STATE_PATH.parent,
                    prefix=".last_negotiation_state.", suffix=".tmp", delete=False,
                ) as stream:
                    temp_path = Path(stream.name)
                    json.dump(state, stream, ensure_ascii=False, indent=2, default=str)
                    stream.write("\n")
                os.replace(temp_path, DEBUG_STATE_PATH)
        except OSError as exc:
            log.warning("Could not write negotiation debug file %s: %s", DEBUG_STATE_PATH, exc)
        finally:
            if temp_path and temp_path.exists():
                try:
                    temp_path.unlink()
                except OSError:
                    pass

    def _negotiate(self, case, threads, data_brief):
        self.brief = data_brief["brief"]

        live = live_threads(threads)
        if not live:
            self._last_negotiation_meta = {"kind": "fallback", "decision_summary": "No live supplier threads."}
            return self.fallback.decide(case, threads)

        states = {sid: self._state(case, sid, threads[sid]) for sid in live}
        # Compare each supplier with the best option that does not include its own quote.
        batnas = {
            sid: self._batna(case, {other: ev for other, ev in threads.items() if other != sid}, {})
            for sid in live
        }
        for sid, state in states.items():
            state["batna"] = batnas[sid]
            state["ceiling_price"] = self.max_price_for_cost(
                case, state["terms"] or {"unit_price": state["target_price"]},
                state["standard"], batnas[sid]["cost"],
            )
            state["target_price"] = min(state["target_price"], state["ceiling_price"])
            target_terms = self.offer_terms(case, state["terms"], state["target_price"])
            state["target_cost"] = total_cost(case, target_terms, state["standard"])

        # Take the best standing offer once it reaches our evidence-based target. A final offer is
        # judged against the hard BATNA ceiling, since there is no useful next counteroffer.
        acceptable = []
        for sid, state in states.items():
            if not state["sheet_id"] or not state["valid"]:
                continue
            status = latest(threads[sid]).get("status")
            cap = batnas[sid]["cost"]
            meets_target = state["cost"] <= state["target_cost"] + 0.01
            terminal_offer = status in {"final_offer", "agreed"} or moves_left(case, threads[sid]) <= 0
            if state["cost"] <= cap + 0.01 and (meets_target or terminal_offer):
                acceptable.append((state["cost"], sid, state["sheet_id"]))
        if acceptable:
            _, sid, offer_id = min(acceptable)
            self._last_negotiation_meta = {
                "kind": "accept",
                "supplier_id": sid,
                "target_price": states[sid]["target_price"],
                "walk_away_price": states[sid]["ceiling_price"],
                "decision_summary": "Standing offer is within BATNA and meets target or is a terminal offer.",
                "data_rebuttal": "",
            }
            return {"supplier_id": sid, "message": {"action": {"type": "accept", "term_sheet_id": offer_id}}}

        negotiable = [
            sid for sid in live
            if moves_left(case, threads[sid]) > 0
            and latest(threads[sid]).get("status") not in {"final_offer", "agreed"}
        ]
        if not negotiable:
            # The action closes the case, so use it only after every live quote is exhausted.
            self._last_negotiation_meta = {
                "kind": "walk_away",
                "decision_summary": "No remaining supplier thread can be negotiated and no standing offer beats BATNA.",
                "data_rebuttal": "",
            }
            return {"supplier_id": live[0], "message": {"action": {"type": "walk_away"}}}

        # Favor a quoted supplier with the lowest current total cost. If no one has quoted a price
        # yet, work the first open RFQ. Other suppliers' live terms become concrete leverage below.
        quoted = [sid for sid in negotiable if states[sid]["sheet_id"] and math.isfinite(states[sid]["cost"])]
        sid = min(quoted, key=lambda s: states[s]["cost"]) if quoted else negotiable[0]
        state = states[sid]
        turn = sum(m.get("from") == "buyer" for m in threads[sid])
        target = state["target_price"]
        curve_steps = max(1, min(self.MAX_CURVE_ROUNDS, case.get("round_limit", 10) - 1))
        fraction = self.FIRST_DISCOUNT * min(turn, curve_steps) / curve_steps
        proposed = min(state["ceiling_price"], target * (1 - self.FIRST_DISCOUNT + fraction))
        proposed = max(0.01, round(proposed, 2))
        terms = self.offer_terms(case, state["terms"], proposed)
        # Snapping or non-price terms can alter total cost. Pull the price down if necessary so
        # every actual offer remains inside the hard BATNA ceiling.
        terms = self.cap_offer(case, terms, state["standard"], batnas[sid]["cost"])

        peer = self.best_peer_quote(case, sid, states)
        data_line = self.data_rebuttal_line(threads[sid])
        history_line = self.contract_rebuttal_line(case, sid, state["terms"])
        prompt = self.render(case, threads, sid, terms, state, batnas[sid], peer, data_line, history_line)
        draft = self.draft(prompt, target, state["ceiling_price"])
        body = self.compose_email(draft, data_line, history_line, peer, terms)
        body = self.filter_ids(case, threads, body)
        subject = draft.get("subject") or f"Re: {case['title']}"
        self._last_negotiation_meta = {
            "kind": "send",
            "supplier_id": sid,
            "target_price": state["target_price"],
            "walk_away_price": state["ceiling_price"],
            "binding_offer": terms,
            "decision_summary": draft.get("analysis", ""),
            "data_rebuttal": data_line,
            "model_data_rebuttal": draft.get("data_rebuttal", ""),
            "contract_comparison": history_line,
        }
        return {
            "supplier_id": sid,
            "message": {
                "subject": str(subject)[:300],
                "body": body[:8000],
                "term_sheets": [{"terms": terms}],
            },
        }

    def prepare(self, case):
        """Build case context from case facts and the local read-only package."""
        out = [f"CASE FILE\n{json.dumps(case, ensure_ascii=False, default=str)}"]
        if self.package and case.get("trigger_doc"):
            try:
                out.append(f"LETTER\n{self.package.document(case['trigger_doc'])[:2500]}")
            except (FileNotFoundError, ValueError):
                pass
        out.append("FACTS (verified lookup by citable ID)")
        refs = dict.fromkeys(case.get("suppliers", []) + case.get("parts", []) + case.get("refs", []))
        for ref in refs:
            if fact := self.fact(case, ref):
                out.append(f"{ref}: {json.dumps(fact, ensure_ascii=False, default=str)[:600]}")
        if self._evidence:
            out.append("MARKET INDEX EVIDENCE (Python-calculated deltas; IDs are citable)")
            out.extend(self._format_evidence(e) for e in self._evidence)
        if self._contracts:
            out.append("LOCAL CONTRACT HISTORY (SQLite rows; use only if part/supplier/terms match)")
            out.extend(json.dumps(row, ensure_ascii=False, default=str)[:700] for row in self._contracts)
        return "\n".join(out)

    def fact(self, case, ref):
        return case.get("facts", {}).get(ref) or (self.package and self.package.lookup(ref))

    def market_evidence(self, case):
        """Compute latest approximately year-over-year index changes for this part's cost drivers."""
        if not self.package:
            return self.case_index_evidence(case)
        drivers = []
        try:
            tables = self.package.tables()
            if "cost_drivers" in tables:
                cols = {c.split()[0] for c in tables["cost_drivers"]["columns"]}
                if {"part_id", "series_id", "weight"} <= cols:
                    for part in case.get("parts", []):
                        drivers.extend(self.package.query(
                            "SELECT part_id, series_id, weight FROM cost_drivers WHERE part_id = ?",
                            (part,), limit=50,
                        ))
        except (ValueError, KeyError, OSError, sqlite3.OperationalError):
            log.debug("Could not read cost drivers", exc_info=True)

        series_weights = {}
        for row in drivers:
            series_weights[row["series_id"]] = float(row.get("weight") or 0)
        if not series_weights:
            for entry in self.case_index_evidence(case):
                series_weights.setdefault(entry["series"], 0.0)

        out = []
        for series, weight in series_weights.items():
            rows = []
            try:
                rows = self.package.query(
                    "SELECT id, month, value FROM index_values WHERE series_id = ? ORDER BY month",
                    (series,), limit=500,
                )
            except (ValueError, KeyError, OSError, sqlite3.OperationalError):
                pass
            if len(rows) < 2:
                cached = next((entry for entry in self.case_index_evidence(case, series=series)), None)
                if cached:
                    out.append({**cached, "weight": weight})
                continue
            start, end = rows[0], rows[-1]
            # Prefer a point about 12 months before the latest observation when available.
            end_year, end_month = self._year_month(end.get("month", ""))
            if end_year is not None:
                target = end_year * 12 + end_month - 12
                start = min(
                    rows[:-1],
                    key=lambda r: abs((self._year_month(r.get("month", ""))[0] or 0) * 12
                                     + (self._year_month(r.get("month", ""))[1] or 0) - target),
                )
            try:
                delta = (float(end["value"]) / float(start["value"]) - 1) * 100
            except (KeyError, TypeError, ValueError, ZeroDivisionError):
                continue
            id_start, id_end = start.get("id"), end.get("id")
            if not id_start or not id_end:
                continue
            out.append({
                "series": series, "weight": weight, "delta_pct": delta,
                "start_month": start.get("month"), "end_month": end.get("month"),
                "start_id": id_start, "end_id": id_end,
            })
        return out[:8]

    @staticmethod
    def _year_month(value):
        try:
            year, month = value[:7].split("-")
            return int(year), int(month)
        except (ValueError, AttributeError):
            return None, None

    def case_index_evidence(self, case, series=None):
        grouped = {}
        refs = set(case.get("facts", {}))
        refs.update(ref for ref in case.get("refs", []) if ref.startswith("idx:"))
        for ref in refs:
            if not ref.startswith("idx:"):
                continue
            fact = self.fact(case, ref) or {}
            name = fact.get("series") or ref.split(":", 1)[-1].split("@", 1)[0]
            if series and name != series:
                continue
            if fact.get("month") is not None and fact.get("value") is not None:
                grouped.setdefault(name, []).append({"id": ref, **fact})
        out = []
        for name, rows in grouped.items():
            if len(rows) >= 2:
                rows.sort(key=lambda r: r["month"])
                out.append({
                    "series": name, "weight": 0.0,
                    "delta_pct": (float(rows[-1]["value"]) / float(rows[0]["value"]) - 1) * 100,
                    "start_month": rows[0]["month"], "end_month": rows[-1]["month"],
                    "start_id": rows[0]["id"], "end_id": rows[-1]["id"],
                })
        return out

    def contract_history(self, case):
        """Read a few matching supplier/part rows from SQLite, without assuming a schema."""
        if not self.package or not getattr(self.package, "db", None):
            return []
        suppliers, parts, output = case.get("suppliers", []), case.get("parts", []), []
        try:
            for table, meta in self.package.tables().items():
                cols = [c.split()[0] for c in meta["columns"]]
                if not IDENTIFIER.fullmatch(table) or any(not IDENTIFIER.fullmatch(c) for c in cols):
                    continue
                lower = {c.lower(): c for c in cols}
                supplier_col = next((lower[k] for k in ("supplier_id", "supplier") if k in lower), None)
                part_col = next((lower[k] for k in ("part_id", "part") if k in lower), None)
                if not supplier_col or not part_col:
                    continue
                predicates, params = [], []
                if supplier_col and suppliers:
                    predicates.append(f'"{supplier_col}" IN ({",".join("?" for _ in suppliers)})')
                    params.extend(suppliers)
                if part_col and parts:
                    predicates.append(f'"{part_col}" IN ({",".join("?" for _ in parts)})')
                    params.extend(parts)
                if not predicates:
                    continue
                date_col = next(
                    (lower[k] for k in ("date", "month", "valid_from", "contract_date", "ordered_at") if k in lower),
                    None,
                )
                order = f' ORDER BY "{date_col}" DESC' if date_col else ""
                rows = self.package.query(
                    f'SELECT * FROM "{table}" WHERE {" AND ".join(predicates)}{order} LIMIT 4',
                    params,
                    limit=4,
                )
                output.extend({"table": table, **row} for row in rows)
        except (ValueError, KeyError, OSError, sqlite3.OperationalError):
            log.debug("Could not read contract history", exc_info=True)
        return output[:12]

    @staticmethod
    def _format_evidence(entry):
        return (
            f"{entry['series']}: {entry['delta_pct']:+.1f}% from {entry['start_month']} to "
            f"{entry['end_month']} ({entry['start_id']}, {entry['end_id']}); "
            f"cost-driver weight={entry.get('weight', 0):g}"
        )

    def data_rebuttal_line(self, events=None):
        """A ready-to-use sentence containing only code-verified index values and citable IDs."""
        if not self._evidence:
            return ""
        selected = sorted(self._evidence, key=lambda e: e.get("weight", 0), reverse=True)[:2]
        evidence = " ".join(
            f"{e['series']} changed {e['delta_pct']:+.1f}% from {e['start_month']} to "
            f"{e['end_month']} ({e['start_id']}, {e['end_id']})."
            for e in selected
        )
        claim = self.supplier_percentage_claim(events) if events else None
        claim = self.supplier_percentage_claim(events) if events else None
        if claim:
            return f"Your email cites a {claim} increase. {evidence} Could you help reconcile the difference?"
        return evidence

    @staticmethod
    def supplier_percentage_claim(events):
        """Return a percentage explicitly stated in the supplier's latest email, if any."""
        if not events:
            return None
        body = latest(events).get("body", "")
        for match in re.finditer(r"([+-]?\d+(?:[.,]\d+)?)\s*%", body):
            context = body[max(0, match.start() - 80):match.end() + 80].lower()
            if any(word in context for word in ("price", "cost", "inflation", "increase", "rise", "surcharge", "material")):
                return f"{match.group(1).replace(',', '.')}%"
        return None

    def contract_rebuttal_line(self, case, sid, terms):
        """Compare a quote with a citable historical purchase for the same supplier and part."""
        candidates = []
        parts = set(case.get("parts", []))
        price_fields = (
            "unit_price", "price_per_unit", "unit_price_eur", "price_eur",
            "price_eur_per_unit", "agreed_unit_price",
        )
        date_fields = ("date", "month", "valid_from", "contract_date", "ordered_at")
        for wrapped in self._contracts:
            row = {k.lower(): v for k, v in wrapped.items()}
            row_id = row.get("id") or next(
                (value for value in wrapped.values() if isinstance(value, str) and ID_RE.fullmatch(value)),
                None,
            )
            if not row_id or not self.fact(case, row_id):
                continue
            supplier = row.get("supplier_id", row.get("supplier"))
            part = row.get("part_id", row.get("part"))
            if supplier != sid:
                continue
            if part not in parts:
                continue
            historical_price = next((row[k] for k in price_fields if row.get(k) is not None), None)
            if historical_price is None:
                continue
            try:
                historical_price = float(historical_price)
                current_price = float((terms or {}).get("unit_price"))
            except (TypeError, ValueError):
                continue
            if historical_price <= 0 or current_price <= 0:
                continue
            date_value = next((row[k] for k in date_fields if row.get(k) is not None), None)
            candidates.append((str(date_value or ""), historical_price, current_price, row_id))
        if not candidates:
            return ""
        date_value, historical_price, current_price, row_id = max(candidates)
        change = (current_price / historical_price - 1) * 100
        date_text = f" dated {date_value}" if date_value else ""
        return (
            f"Our last matched purchase record lists EUR {historical_price:.2f}/unit{date_text} "
            f"({row_id}); your current quote is {change:+.1f}% against that record."
        )

    def _state(self, case, sid, events):
        sheet_id, terms = standing(events)
        std = standard_terms(events)
        terms = complete_offer(case, terms) if terms.get("unit_price") is not None else {}
        cost = total_cost(case, terms, std) if terms else math.inf
        valid = bool(terms) and must_haves_ok(case, terms, std)
        target_price = self.target_price(case, terms)
        target_terms = self.offer_terms(case, terms, target_price) if terms else complete_offer(
            case, {"unit_price": target_price}
        )
        # Target cost is filled against this supplier's quoted standard terms below.
        target_cost = total_cost(case, target_terms, std)
        # The actual ceiling is supplier-specific because standard terms affect total cost.
        ceiling = self.max_price_for_cost(case, terms or target_terms, std, self.reference_cost(case, {}))
        return {
            "sheet_id": sheet_id, "terms": terms, "standard": std, "cost": cost, "valid": valid,
            "target_price": min(target_price, ceiling), "target_cost": target_cost,
            "ceiling_price": ceiling,
        }

    def target_price(self, case, terms):
        buyer = case["buyer"]
        current = buyer.get("current_unit_price")
        if current is None:
            alt = buyer.get("alternative") or {}
            current = (alt.get("terms") or {}).get("unit_price") or buyer.get("fallback_unit_price")
        if current is None:
            current = (terms or {}).get("unit_price") or 1.0
        changes = [(e.get("weight", 0), e["delta_pct"]) for e in self._evidence if e.get("weight", 0) > 0]
        total_weight = sum(w for w, _ in changes)
        delta = sum(w * d for w, d in changes) if changes else 0.0
        if total_weight > 1.0:
            delta /= total_weight
        # Do not award an automatic premium for deflation; the observed basket only adjusts a
        # historical price when weighted drivers support an increase.
        adjusted = float(current) * (1 + max(0.0, delta) / 100)
        return round(max(0.01, adjusted), 2)

    def _batna(self, case, threads, states):
        choices = []
        alt = case["buyer"].get("alternative") or {}
        if alt.get("terms", {}).get("unit_price") is not None and must_haves_ok(case, alt["terms"]):
            c = total_cost(case, alt["terms"])
            choices.append((c, "documented alternative"))
        for sid, events in threads.items():
            sheet_id, terms = standing(events)
            if not sheet_id or terms.get("unit_price") is None:
                continue
            std = standard_terms(events)
            if must_haves_ok(case, terms, std):
                choices.append((total_cost(case, terms, std), f"live quote {sid}"))
        fallback = case["buyer"].get("fallback_unit_price")
        if fallback is not None:
            terms = self.offer_terms(case, {}, fallback)
            if must_haves_ok(case, terms):
                choices.append((total_cost(case, terms), "fallback supply"))
        if not choices:
            return {"cost": math.inf, "source": "no priced alternative"}
        cost, source = min(choices)
        return {"cost": cost, "source": source}

    def reference_cost(self, case, threads):
        return self._batna(case, threads, {})["cost"]

    def max_price_for_cost(self, case, template, standard, cap):
        if not math.isfinite(cap):
            return max(0.01, float((template or {}).get("unit_price") or case["buyer"].get("current_unit_price") or 1) * 2)
        base = dict(template or complete_offer(case, {"unit_price": 1.0}))
        low, high = 0.01, max(100.0, float(base.get("unit_price") or 1.0) * 8)
        for _ in range(48):
            mid = (low + high) / 2
            offer = self.offer_terms(case, base, mid)
            if total_cost(case, offer, standard) <= cap + 0.01:
                low = mid
            else:
                high = mid
        return round(low, 2)

    def offer_terms(self, case, current_terms, price):
        terms = complete_offer(case, {**(current_terms or {}), "unit_price": price})
        options = case.get("term_options", {})
        for must in case["buyer"].get("must_haves", []):
            field, op, required = must["field"], must["op"], must["value"]
            value = terms.get(field)
            if value is not None and OPS[op](value, required):
                continue
            candidates = list(options.get(field, [])) + [required]
            valid = [candidate for candidate in candidates if OPS[op](candidate, required)]
            if valid:
                # Select the least costly numeric value for the buyer; otherwise use the first
                # valid enumerated value. The cost cap is checked after this completion.
                if all(isinstance(v, int | float) for v in valid):
                    terms[field] = min(valid)
                else:
                    terms[field] = valid[0]
        return complete_offer(case, terms)

    def cap_offer(self, case, terms, standard, cap):
        if not math.isfinite(cap) or total_cost(case, terms, standard) <= cap + 0.01:
            return terms
        ceiling = self.max_price_for_cost(case, terms, standard, cap)
        return self.offer_terms(case, terms, max(0.01, min(terms.get("unit_price") or ceiling, ceiling)))

    def best_peer_quote(self, case, sid, states):
        peers = [
            (state["cost"], other, state, True)
            for other, state in states.items()
            if other != sid and state["sheet_id"] and state["terms"].get("unit_price") is not None
            and state["valid"]
        ]
        alternative = case["buyer"].get("alternative") or {}
        alternative_terms = alternative.get("terms") or {}
        if alternative_terms.get("unit_price") is not None and must_haves_ok(case, alternative_terms):
            peers.append((
                total_cost(case, alternative_terms),
                alternative.get("ref") or "documented alternative",
                {"terms": alternative_terms, "sheet_id": alternative.get("ref")},
                False,
            ))
        if not peers:
            return None
        _, other, state, is_live = min(peers, key=lambda item: (item[0], str(item[1])))
        return {
            "supplier_id": other if is_live else None,
            "offer_id": state.get("sheet_id"),
            "unit_price": state["terms"]["unit_price"],
            "cost": state.get("cost", total_cost(case, state["terms"])),
            "live": is_live,
        }

    def render(self, case, threads, sid, terms, state, batna, peer, data_line, history_line):
        out = [self.brief, f"\nSELECTED THREAD: {sid}"]
        out.append(f"PYTHON OFFER (binding term sheet): {json.dumps(terms, ensure_ascii=False)}")
        out.append(
            f"TARGET PRICE: EUR {state['target_price']:.2f}/unit. WALK-AWAY CEILING: "
            f"EUR {state['ceiling_price']:.2f}/unit. BATNA total cost: EUR {batna['cost']:.2f} ({batna['source']})."
        )
        if data_line:
            out.append(f"PYTHON-VERIFIED DATA REBUTTAL: {data_line}")
        if history_line:
            out.append(f"PYTHON-VERIFIED CONTRACT HISTORY COMPARISON: {history_line}")
        if peer:
            source = f"{peer['supplier_id']} offered" if peer["live"] else "The documented alternative is"
            reference = f" ({peer['offer_id']})" if peer.get("offer_id") else ""
            out.append(f"COMPETING ALTERNATIVE: {source} EUR {peer['unit_price']:.2f}/unit{reference}; use it tactfully.")
        out.append("Write the email body only; the strategy, exact offer, and external action are fixed by Python.")
        for thread_id in live_threads(threads):
            events = threads[thread_id]
            sheet_id, standing_terms = standing(events)
            std = standard_terms(events)
            total = total_cost(case, standing_terms, std) if standing_terms.get("unit_price") is not None else math.inf
            out.append(
                f"\nTHREAD {thread_id}: status {latest(events).get('status')}, "
                f"{moves_left(case, events)} messages left; standing {sheet_id} "
                f"{json.dumps(standing_terms)} -> C = {total:,.2f}; standard terms {json.dumps(std)}"
            )
            for message in events[-5:]:
                head = {k: message.get(k) for k in ("status", "term_sheets", "missing_fields", "claim_results") if message.get(k)}
                out.append(f"--- {message.get('from')}: {json.dumps(head, ensure_ascii=False)}\n{message.get('body', '')[:800]}")
                for att in message.get("attachments") or []:
                    out.append(f"[attachment {att.get('name')}]\n{att.get('text', '')[:1500]}")
        return "\n".join(out)

    def draft(self, prompt, target, ceiling):
        try:
            data = parse(self.complete(SYSTEM, prompt))
            if not isinstance(data, dict):
                raise ValueError("model response is not an object")
            return {
                "analysis": str(data.get("analysis", "")),
                "data_rebuttal": str(data.get("data_rebuttal", "")),
                "target_price": target,
                "walk_away_price": ceiling,
                "email_body": str(data.get("email_body", data.get("body", ""))).strip(),
                "subject": data.get("subject"),
            }
        except Exception as exc:  # the state machine still works if the model is slow or broken
            log.warning("LLM drafting failed (%s) - using a grounded email template", exc)
            return {
                "analysis": "Use the Python-calculated offer and verified case evidence.",
                "data_rebuttal": "",
                "target_price": target,
                "walk_away_price": ceiling,
                "email_body": "How are we supposed to absorb this without shifting volume? Could you share an itemized cost breakdown and explain where you have flexibility?",
            }

    def compose_email(self, draft, data_line, history_line, peer, terms):
        parts = []
        if data_line:
            parts.append(data_line)
        if history_line:
            parts.append(history_line)
        if peer:
            if peer["live"]:
                comparison = f"We have a competing offer at EUR {peer['unit_price']:.2f}/unit"
            else:
                comparison = f"Our documented alternative is EUR {peer['unit_price']:.2f}/unit"
            if peer.get("offer_id"):
                comparison += f" ({peer['offer_id']})"
            parts.append(f"{comparison}; can you improve on EUR {terms['unit_price']:.2f}/unit?")
        else:
            parts.append(f"Our counteroffer is EUR {terms['unit_price']:.2f}/unit on the attached terms.")
        if draft.get("email_body"):
            room = max(15, 120 - len(" ".join(parts).split()))
            parts.append(" ".join(draft["email_body"].split()[:room]))
        else:
            parts.append("How are we supposed to absorb this without shifting volume? Could you share an itemized cost breakdown?")
        body = " ".join(" ".join(part.split()) for part in parts)
        words = body.split()
        return " ".join(words[:120])

    def filter_ids(self, case, threads, body):
        offers = {standing(events)[0] for events in threads.values() if standing(events)[0]}

        def known(match):
            ref = match.group(0)
            if ref in offers or self.fact(case, ref):
                return ref
            log.warning("dropped unknown data ID %s", ref)
            return ""

        return re.sub(r"\s*\(\s*[,;\s]*\)", "", ID_RE.sub(known, body)).strip()


def parse(text):
    """Read the first JSON object, tolerating code fences and leading commentary."""
    decoder = json.JSONDecoder()
    for match in re.finditer(r"\{", text):
        try:
            value, _ = decoder.raw_decode(text[match.start():])
            if isinstance(value, dict):
                return value
        except json.JSONDecodeError:
            continue
    raise ValueError(f"no JSON object in reply: {text[:200]}")
"""The published cost function: what a term sheet costs the buyer in €, plus term helpers.

C covers the buyer's fixed need over a fixed horizon: need the deal does not cover is bought at
the case's fallback price (plus the fallback risk of the category goal), committed volume is bought
needed or not, and units bought before a new price takes effect cost the current price. In
strategic and bottleneck cases a deal that leaves the supplier below a sustainable margin costs
too - pass your estimate of the supplier (`supplier_value`) to price that. Do the arithmetic here,
not in the language model.
"""

import math
import operator
from datetime import date

# Strategic and bottleneck goals: leaving the supplier below a sustainable margin costs.
RELATIONSHIP_GOALS = {"stabilise", "secure_supply"}
OPS = {
    "<=": operator.le,
    "<": operator.lt,
    ">=": operator.ge,
    ">": operator.gt,
    "==": operator.eq,
    "!=": operator.ne,
}


def closing_terms(case, terms, standard=None):
    """The terms a deal would close on: the term sheet, then the supplier's standard terms (from
    its quote PDF) for anything left out, then the case's fixed terms; gaps from the buyer's plan.
    """
    b = case["buyer"]
    freight = b["freight_eur_per_unit"]
    plan = {
        "volume_per_year": b["need_per_year"],
        "contract_months": round(12 * b["horizon_years"]),
        "payment_days": b["reference_payment_days"],
        "lead_time_days": b["need_lead_time_days"],
        # an unknown Incoterm counts as the costliest: a cautious buyer does not assume DAP
        "incoterm": max(freight, key=freight.get),
    }
    t = dict(plan)
    for layer in (standard or {}, case.get("fixed_terms", {}), terms):
        t.update({k: v for k, v in layer.items() if v is not None or k not in plan})
    return t


def horizon_start(case):
    """The horizon starts at the fixed or the earliest possible effective date."""
    fixed = case.get("fixed_terms", {}).get("effective_date")
    options = [o for o in case.get("term_options", {}).get("effective_date", []) if o]
    first = fixed or (min(options) if options else None)
    return date.fromisoformat(first) if first else None


def _years(case, t):
    """Years of the horizon a deal covers; a single order (0 months) counts as one year's lot.
    A commitment beyond the horizon neither costs nor earns."""
    months = t["contract_months"]
    return min(months / 12 if months else 1.0, case["buyer"]["horizon_years"])


def _units_before(case, t, years):
    """Units bought between the horizon start and the date a new price takes effect."""
    start = horizon_start(case)
    if not t.get("effective_date") or start is None:
        return 0.0
    lag = (date.fromisoformat(t["effective_date"]) - start).days / 365
    return t["volume_per_year"] * min(max(lag, 0.0), years)


def supplier_value(case, terms, supplier):
    """What a deal is worth to the supplier per unit, in cash: the price at its standard terms that
    would pay it the same. `supplier` is your estimate of it:
      standard       its standard terms (quote PDF, `docs.standard_terms`)
      interest_rate  what money now is worth to it per year (more to a supplier short of cash)
      usual_rate     its usual cost of money (default: interest_rate); tooling paid up front is
                     worth more to it when cash is dearer than usual
      ppm            the defect rate it really achieves (default: its standard ppm commitment)
      extra          EUR per unit it gains (+) or spends (-) beyond these items, e.g. overtime for
                     a faster delivery or idle capacity a larger volume fills (default 0)
    Contract length and an index clause are security, not cash: they do not count here."""
    b, std = case["buyer"], {**supplier["standard"], **case.get("fixed_terms", {})}
    t = closing_terms(case, terms, std)
    years = _years(case, t)
    sold = t["volume_per_year"] * years
    old = _units_before(case, t, years) / sold  # sold at the current price
    rate = supplier["interest_rate"]
    pay = 1 - rate * (t["payment_days"] - std["payment_days"]) / 360
    cash_now = 1 + (rate - supplier.get("usual_rate", rate)) * years / 2
    freight = b["freight_eur_per_unit"]
    ppm = supplier.get("ppm", std.get("ppm_commitment") or 0)
    return (
        t["unit_price"] * (1 - old) * pay
        + old * (b.get("current_unit_price") or 0.0) * pay
        + freight[t["incoterm"]]
        - freight[std["incoterm"]]  # it carries the freight leg
        + ((t.get("tooling_eur") or 0) - (std.get("tooling_eur") or 0)) / sold * cash_now
        - ppm / 1e6 * ((t.get("chargeback_eur_per_complaint") or 0) - (std.get("chargeback_eur_per_complaint") or 0))
        + supplier.get("extra", 0.0)
    )


def _soft(gap):
    """Margin points below the sustainable margin, as they cost: none above it, quadratic over
    the first 5 points, linear beyond - no kink."""
    if gap <= 0:
        return 0.0
    return gap * gap / 10 if gap <= 5 else gap - 2.5


def relationship_cost(case, terms, standard=None, supplier=None, value=None):
    """Strategic and bottleneck goals only: EUR for every margin point the deal leaves the supplier
    below `sustainable_margin_pct`, per year covered. `supplier["full_cost"]` (EUR per unit) is your
    estimate of its full cost; `value` overrides `supplier_value`. Without an estimate: 0."""
    b = case["buyer"]
    per_point, sustainable = b.get("relationship_eur_per_point"), b.get("sustainable_margin_pct")
    if b.get("category_goal") not in RELATIONSHIP_GOALS or not per_point or not sustainable or not supplier:
        return 0.0
    t = closing_terms(case, terms, standard)
    worth = value if value is not None else supplier_value(case, t, supplier)
    margin = (worth - supplier["full_cost"]) / worth * 100
    return per_point * _soft(sustainable - margin) * _years(case, t)


def cost_breakdown(case, terms, standard=None, supplier=None):
    """C by part. `standard`: the supplier's standard terms for anything the term sheet leaves out.
    `supplier`: your estimate of the supplier for the relationship term (`supplier_value`)."""
    b, t = case["buyer"], closing_terms(case, terms, standard)
    if t.get("unit_price") is None:
        raise ValueError("no unit_price: a term sheet without a price has no cost")
    years = _years(case, t)
    committed = t["volume_per_year"] * years  # bought, needed or not
    covered = min(t["volume_per_year"], b["need_per_year"]) * years
    pre = _units_before(case, t, years)
    at_new_price = (committed - pre) * t["unit_price"]
    spend = pre * (b.get("current_unit_price") or t["unit_price"]) + at_new_price
    per_defect = b.get("cost_per_defect", 0)
    defect_cost = per_defect - min(t.get("chargeback_eur_per_complaint") or 0, per_defect)
    index = index_risk = 0.0
    if clause := t.get("index_clause"):
        path = b.get("index_paths", {}).get(clause["series"], 0.0)
        moved = max(0.0, abs(path) - clause["deadband_pct"] / 100)
        index = at_new_price * clause["material_share"] * moved * math.copysign(1, path)
        index_risk = at_new_price * clause["material_share"] * b.get("index_risk_pct", 0) / 100
    uncovered = (b["need_per_year"] * b["horizon_years"] - covered) * b["fallback_unit_price"]
    need = b["need_lead_time_days"]
    return {
        "price": spend,
        "uncovered_need": uncovered,
        "fallback_risk": uncovered * b.get("fallback_risk_pct", 0) / 100,
        "payment_terms": spend * b["interest_rate"] * (b["reference_payment_days"] - t["payment_days"]) / 360,
        "freight": committed * b["freight_eur_per_unit"][t["incoterm"]],
        "late_delivery": b.get("late_cost_per_day", 0) * max(0, t["lead_time_days"] - need),
        "quality": committed * (t.get("ppm_commitment") or 0) / 1e6 * defect_cost,
        "tooling": t.get("tooling_eur") or 0.0,
        "index_clause": index,
        "index_risk": index_risk,
        "relationship": relationship_cost(case, t, supplier=supplier),
    }


def total_cost(case, terms, standard=None, supplier=None):
    """C in EUR; infinite for terms without a price (e.g. a supplier that quotes none), so such a
    sheet is never the cheapest and never beats an alternative."""
    if closing_terms(case, terms, standard).get("unit_price") is None:
        return math.inf
    return round(sum(cost_breakdown(case, terms, standard, supplier).values()), 2)


def score(c_open, c_deal, c_best):
    if c_deal is None:
        return 0.0
    if c_open - c_best <= 0.01:  # no room to negotiate: matching the best is full marks
        return 1.0 if c_deal <= c_best + 0.01 else 0.0
    return min(1.0, max(0.0, (c_open - c_deal) / (c_open - c_best)))


def must_haves_ok(case, terms, standard=None):
    t = closing_terms(case, terms, standard)
    for m in case["buyer"].get("must_haves", []):
        value = t.get(m["field"])
        if value is None and m["op"] not in ("==", "!="):
            return False
        if not OPS[m["op"]](value, m["value"]):
            return False
    return True


def snap(case, field, value):
    """The allowed value closest to `value` (case `term_options`), else `value` unchanged."""
    options = case.get("term_options", {}).get(field)
    if not options or value in options:
        return value
    if isinstance(value, int | float) and all(isinstance(o, int | float) for o in options):
        return min(options, key=lambda o: (abs(o - value), o))
    return options[0]


def complete_offer(case, terms):
    """A valid term sheet: exactly the negotiable fields, gaps from the buyer's plan, snapped."""
    plan = closing_terms(case, {"unit_price": None})
    freight = case["buyer"]["freight_eur_per_unit"]
    plan["incoterm"] = min(freight, key=freight.get)  # when asking, ask for the cheapest freight
    out = {}
    for field in case["negotiable"]:
        value = terms.get(field, plan.get(field))
        if value is None and case.get("term_options", {}).get(field):
            value = case["term_options"][field][0]
        value = snap(case, field, value)
        out[field] = round(value, 2) if field == "unit_price" and value is not None else value
    return out
"""Play cases with an agent against the arena over HTTP - the hosted arena (practice, sandbox,
final) or `arena-sim`, the local contract simulator. Both speak the same API.

An agent is any object with `decide(case, threads) -> {"supplier_id": ..., "message": {...}}`:
  threads: {supplier_id: [message, ...]} - every e-mail so far, both directions, in order;
           supplier attachments carry their text under "text" (see `docs.read_document`).
  message: subject, body, up to 3 term sheets, refs - or an "action" that closes the case:
           {"type": "accept", "term_sheet_id": ...} or {"type": "walk_away"}.
"""

import functools
import logging
import re
import threading
import time
from concurrent.futures import ThreadPoolExecutor

from .client import ArenaError
from .cost import must_haves_ok, total_cost
from .docs import read_document, standard_terms

log = logging.getLogger("arena")

ENDED = {"walked_away", "no_bid"}
# A message later than this after the supplier's last one counts as a timeout.
MOVE_LIMIT_S = 60
# In the Live Final, close this long before the wave's cap - or the slowest round of the case so far
# (your decision plus a supplier reply of up to about a minute) plus a margin, if that is longer.
CLOSE_BEFORE_CAP_S, ROUND_MARGIN_S = 90, 15
RUNNING = re.compile(r"one session per case in the final: (\S+)")
# Practice: the case list shows every practice case file; only those marked hosted can be played
# (a session on another is a 403). Without the marker every listed case counts as hosted.
HOSTED_FIELD = "hosted"


class RemoteTable:
    """The arena over HTTP: the practice arena, the final, or a hosted sandbox."""

    def __init__(self, client, case=None):
        self.client, self.session_id, self.case, self.done = client, None, case, None

    def open(self, case_id):
        try:
            r = self.client.open_session(case_id)
        except ArenaError as e:
            running = RUNNING.search(str(e.detail)) if e.status == 409 else None
            if not (running and self.case):
                raise
            return self.resume(running.group(1))
        self.session_id = r["session_id"]
        log.info("session %s", self.session_id)
        return r["case"], r["threads"]

    def resume(self, session_id):
        """Pick up a final session this team already started (e.g. after a crash): every thread
        so far, from the arena."""
        self.session_id = session_id
        log.info("resuming session %s", session_id)
        state = self.client.session(session_id)
        if state["status"] == "ended":
            self.done = self.result()
        return self.case, {s: self.client.thread(session_id, s)["messages"] for s in state["threads"]}

    def send(self, supplier_id, message):
        return self.client.send_message(self.session_id, supplier_id, message)

    def close(self, supplier_id, message):
        reply = self.client.send_message(self.session_id, supplier_id, message)
        return reply.get("result", reply)  # the supplier's last e-mail carries the result

    def attachment(self, attachment_id):
        return self.client.attachment(self.session_id, attachment_id)

    def missed(self, supplier_id, error):
        """After a 409: the result if the case has ended (e.g. at a wave's cap), else what the
        thread now says (a timeout answer, or the reason it ended)."""
        state = self.client.session(self.session_id)
        if state.get("status") == "ended":
            return {"result": state.get("result") or {"deal": False, "end_reason": state.get("end_reason")}}
        t = self.client.thread(self.session_id, supplier_id)
        last = (t.get("timeouts") or [{}])[-1]
        sheet = [{"term_sheet_id": t["offer_id"], "terms": last.get("terms", {})}]
        return {
            "from": "arena",
            "status": "walked_away" if t["closed"] else t["status"],
            "term_sheets": [] if t["closed"] else sheet,
            "body": f"({error.detail})",
            "missing_fields": last.get("missing_fields", []),
            "attachments": [],
        }

    def result(self):
        state = self.client.session(self.session_id)
        return state.get("result") or {"deal": False, "end_reason": state.get("end_reason"), **state}


def latest(events):
    """The supplier's latest message in a thread."""
    return next(m for m in reversed(events) if m.get("from") != "buyer")


def standing(events):
    """(term_sheet_id, terms) of the supplier's standing term sheet, or (None, {})."""
    sheets = latest(events).get("term_sheets") or []
    return (sheets[0]["term_sheet_id"], sheets[0]["terms"]) if sheets else (None, {})


def live_threads(threads):
    """Suppliers whose thread has not ended."""
    return [sid for sid, ev in threads.items() if latest(ev).get("status") not in ENDED]


def moves_left(case, events):
    """Messages you may still send in this thread (the round limit counts each of them)."""
    return case.get("round_limit", 10) - sum(m.get("from") == "buyer" for m in events)


def fetch_documents(table, message):
    """Download every attachment of a supplier message and add its text."""
    for att in message.get("attachments") or []:
