    @staticmethod
    def _year_month(value):
        try:
            year, month = value[:7].split("-")
            return int(year), int(month)
        except (ValueError, AttributeError):
            return None, None

    def case_index_evidence(self, case, series=None):
        grouped = {}
        refs = set(case.get("facts", {}))
        refs.update(ref for ref in case.get("refs", []) if ref.startswith("idx:"))
        for ref in refs:
            if not ref.startswith("idx:"):
                continue
            fact = self.fact(case, ref) or {}
            name = fact.get("series") or ref.split(":", 1)[-1].split("@", 1)[0]
            if series and name != series:
                continue
            if fact.get("month") is not None and fact.get("value") is not None:
                grouped.setdefault(name, []).append({"id": ref, **fact})
        out = []
        for name, rows in grouped.items():
            if len(rows) >= 2:
                rows.sort(key=lambda r: r["month"])
                out.append({
                    "series": name, "weight": 0.0,
                    "delta_pct": (float(rows[-1]["value"]) / float(rows[0]["value"]) - 1) * 100,
                    "start_month": rows[0]["month"], "end_month": rows[-1]["month"],
                    "start_id": rows[0]["id"], "end_id": rows[-1]["id"],
                })
        return out

    def contract_history(self, case):
        """Read a few matching supplier/part rows from SQLite, without assuming a schema."""
        if not self.package or not getattr(self.package, "db", None):
            return []
        suppliers, parts, output = case.get("suppliers", []), case.get("parts", []), []
        try:
            for table, meta in self.package.tables().items():
                cols = [c.split()[0] for c in meta["columns"]]
                if not IDENTIFIER.fullmatch(table) or any(not IDENTIFIER.fullmatch(c) for c in cols):
                    continue
                lower = {c.lower(): c for c in cols}
                supplier_col = next((lower[k] for k in ("supplier_id", "supplier") if k in lower), None)
                part_col = next((lower[k] for k in ("part_id", "part") if k in lower), None)
                if not supplier_col or not part_col:
                    continue
                predicates, params = [], []
                if supplier_col and suppliers:
                    predicates.append(f'"{supplier_col}" IN ({",".join("?" for _ in suppliers)})')
                    params.extend(suppliers)
                if part_col and parts:
                    predicates.append(f'"{part_col}" IN ({",".join("?" for _ in parts)})')
                    params.extend(parts)
                if not predicates:
                    continue
                date_col = next(
                    (lower[k] for k in ("date", "month", "valid_from", "contract_date", "ordered_at") if k in lower),
                    None,
                )
                order = f' ORDER BY "{date_col}" DESC' if date_col else ""
                rows = self.package.query(
                    f'SELECT * FROM "{table}" WHERE {" AND ".join(predicates)}{order} LIMIT 4',
                    params,
                    limit=4,
                )
                output.extend({"table": table, **row} for row in rows)
        except (ValueError, KeyError, OSError, sqlite3.OperationalError):
            log.debug("Could not read contract history", exc_info=True)
        return output[:12]

    @staticmethod
    def _format_evidence(entry):
        return (
            f"{entry['series']}: {entry['delta_pct']:+.1f}% from {entry['start_month']} to "
            f"{entry['end_month']} ({entry['start_id']}, {entry['end_id']}); "
            f"cost-driver weight={entry.get('weight', 0):g}"
        )

    def data_rebuttal_line(self, events=None):
        """A ready-to-use sentence containing only code-verified index values and citable IDs."""
        if not self._evidence:
            return ""
        selected = sorted(self._evidence, key=lambda e: e.get("weight", 0), reverse=True)[:2]
        evidence = " ".join(
            f"{e['series']} changed {e['delta_pct']:+.1f}% from {e['start_month']} to "
            f"{e['end_month']} ({e['start_id']}, {e['end_id']})."
            for e in selected
        )
        claim = self.supplier_percentage_claim(events) if events else None
        if claim:
            return f"Your email cites a {claim} increase. {evidence} Could you help reconcile the difference?"
        return evidence

    @staticmethod
    def supplier_percentage_claim(events):
        """Return a percentage explicitly stated in the supplier's latest email, if any."""
        if not events:
            return None
        body = latest(events).get("body", "")
        for match in re.finditer(r"([+-]?\d+(?:[.,]\d+)?)\s*%", body):
            context = body[max(0, match.start() - 80):match.end() + 80].lower()
            if any(word in context for word in ("price", "cost", "inflation", "increase", "rise", "surcharge", "material")):
                return f"{match.group(1).replace(',', '.')}%"
        return None

    def contract_rebuttal_line(self, case, sid, terms):
        """Compare a quote with a citable historical purchase for the same supplier and part."""
        candidates = []
        parts = set(case.get("parts", []))
        price_fields = (
            "unit_price", "price_per_unit", "unit_price_eur", "price_eur",
            "price_eur_per_unit", "agreed_unit_price",
        )
        date_fields = ("date", "month", "valid_from", "contract_date", "ordered_at")
        for wrapped in self._contracts:
            row = {k.lower(): v for k, v in wrapped.items()}
            row_id = row.get("id") or next(
                (value for value in wrapped.values() if isinstance(value, str) and ID_RE.fullmatch(value)),
                None,
            )
            if not row_id or not self.fact(case, row_id):
                continue
            supplier = row.get("supplier_id", row.get("supplier"))
            part = row.get("part_id", row.get("part"))
            if supplier != sid:
                continue
            if part not in parts:
                continue
            historical_price = next((row[k] for k in price_fields if row.get(k) is not None), None)
            if historical_price is None:
                continue
            try:
                historical_price = float(historical_price)
                current_price = float((terms or {}).get("unit_price"))
            except (TypeError, ValueError):
                continue
            if historical_price <= 0 or current_price <= 0:
                continue
            date_value = next((row[k] for k in date_fields if row.get(k) is not None), None)
            candidates.append((str(date_value or ""), historical_price, current_price, row_id))
        if not candidates:
            return ""
        date_value, historical_price, current_price, row_id = max(candidates)
        change = (current_price / historical_price - 1) * 100
        date_text = f" dated {date_value}" if date_value else ""
        return (
            f"Our last matched purchase record lists EUR {historical_price:.2f}/unit{date_text} "
            f"({row_id}); your current quote is {change:+.1f}% against that record."
        )

    def _state(self, case, sid, events):
        sheet_id, terms = standing(events)
        std = standard_terms(events)
        terms = complete_offer(case, terms) if terms.get("unit_price") is not None else {}
        cost = total_cost(case, terms, std) if terms else math.inf
        valid = bool(terms) and must_haves_ok(case, terms, std)
        target_price = self.target_price(case, terms)
        target_terms = self.offer_terms(case, terms, target_price) if terms else complete_offer(
            case, {"unit_price": target_price}
        )
        # Target cost is filled against this supplier's quoted standard terms below.
        target_cost = total_cost(case, target_terms, std)
        # The actual ceiling is supplier-specific because standard terms affect total cost.
        ceiling = self.max_price_for_cost(case, terms or target_terms, std, self.reference_cost(case, {}))
        return {
            "sheet_id": sheet_id, "terms": terms, "standard": std, "cost": cost, "valid": valid,
            "target_price": min(target_price, ceiling), "target_cost": target_cost,
            "ceiling_price": ceiling,
        }

    def target_price(self, case, terms):
        buyer = case["buyer"]
        current = buyer.get("current_unit_price")
        if current is None:
            alt = buyer.get("alternative") or {}
            current = (alt.get("terms") or {}).get("unit_price") or buyer.get("fallback_unit_price")
        if current is None:
            current = (terms or {}).get("unit_price") or 1.0
        changes = [(e.get("weight", 0), e["delta_pct"]) for e in self._evidence if e.get("weight", 0) > 0]
        total_weight = sum(w for w, _ in changes)
        delta = sum(w * d for w, d in changes) if changes else 0.0
        if total_weight > 1.0:
            delta /= total_weight
        # Do not award an automatic premium for deflation; the observed basket only adjusts a
        # historical price when weighted drivers support an increase.
        adjusted = float(current) * (1 + max(0.0, delta) / 100)
        return round(max(0.01, adjusted), 2)

    def _batna(self, case, threads, states):
        choices = []
        alt = case["buyer"].get("alternative") or {}
        if alt.get("terms", {}).get("unit_price") is not None and must_haves_ok(case, alt["terms"]):
            c = total_cost(case, alt["terms"])
            choices.append((c, "documented alternative"))
        for sid, events in threads.items():
            sheet_id, terms = standing(events)
            if not sheet_id or terms.get("unit_price") is None:
                continue
            std = standard_terms(events)
            if must_haves_ok(case, terms, std):
                choices.append((total_cost(case, terms, std), f"live quote {sid}"))
        fallback = case["buyer"].get("fallback_unit_price")
        if fallback is not None:
            terms = self.offer_terms(case, {}, fallback)
            if must_haves_ok(case, terms):
                choices.append((total_cost(case, terms), "fallback supply"))
        if not choices:
            return {"cost": math.inf, "source": "no priced alternative"}
        cost, source = min(choices)
        return {"cost": cost, "source": source}

    def reference_cost(self, case, threads):
        return self._batna(case, threads, {})["cost"]

    def max_price_for_cost(self, case, template, standard, cap):
        if not math.isfinite(cap):
            return max(0.01, float((template or {}).get("unit_price") or case["buyer"].get("current_unit_price") or 1) * 2)
        base = dict(template or complete_offer(case, {"unit_price": 1.0}))
        low, high = 0.01, max(100.0, float(base.get("unit_price") or 1.0) * 8)
        for _ in range(48):
            mid = (low + high) / 2
            offer = self.offer_terms(case, base, mid)
            if total_cost(case, offer, standard) <= cap + 0.01:
                low = mid
            else:
                high = mid
        return round(low, 2)

    def offer_terms(self, case, current_terms, price):
        terms = complete_offer(case, {**(current_terms or {}), "unit_price": price})
        options = case.get("term_options", {})
        for must in case["buyer"].get("must_haves", []):
            field, op, required = must["field"], must["op"], must["value"]
            value = terms.get(field)
            if value is not None and OPS[op](value, required):
                continue
            candidates = list(options.get(field, [])) + [required]
            valid = [candidate for candidate in candidates if OPS[op](candidate, required)]
            if valid:
                # Select the least costly numeric value for the buyer; otherwise use the first
                # valid enumerated value. The cost cap is checked after this completion.
                if all(isinstance(v, int | float) for v in valid):
                    terms[field] = min(valid)
                else:
                    terms[field] = valid[0]
        return complete_offer(case, terms)

    def cap_offer(self, case, terms, standard, cap):
        if not math.isfinite(cap) or total_cost(case, terms, standard) <= cap + 0.01:
            return terms
        ceiling = self.max_price_for_cost(case, terms, standard, cap)
        return self.offer_terms(case, terms, max(0.01, min(terms.get("unit_price") or ceiling, ceiling)))

    def best_peer_quote(self, case, sid, states):
        peers = [
            (state["cost"], other, state, True)
            for other, state in states.items()
            if other != sid and state["sheet_id"] and state["terms"].get("unit_price") is not None
            and state["valid"]
        ]
        alternative = case["buyer"].get("alternative") or {}
        alternative_terms = alternative.get("terms") or {}
        if alternative_terms.get("unit_price") is not None and must_haves_ok(case, alternative_terms):
            peers.append((
                total_cost(case, alternative_terms),
                alternative.get("ref") or "documented alternative",
                {"terms": alternative_terms, "sheet_id": alternative.get("ref")},
                False,
            ))
        if not peers:
            return None
        _, other, state, is_live = min(peers, key=lambda item: (item[0], str(item[1])))
        return {
            "supplier_id": other if is_live else None,
            "offer_id": state.get("sheet_id"),
            "unit_price": state["terms"]["unit_price"],
            "cost": state.get("cost", total_cost(case, state["terms"])),
            "live": is_live,
